startup:
cd /home/container;

export NPM_CONFIG_PREFIX="/home/container/.npm-global";
export PATH="$NPM_CONFIG_PREFIX/bin:$PATH";
mkdir -p "$NPM_CONFIG_PREFIX";

build_git_url() {
    local url="$1";
    if [[ "$url" != *.git ]]; then
        url="${url%/}.git";
    fi;
    if [ -n "${USERNAME}" ] && [ -n "${ACCESS_TOKEN}" ]; then
        url="https://${USERNAME}:${ACCESS_TOKEN}@$(echo "$url" | cut -d/ -f3-)";
    fi;
    echo "$url";
};

if [ ! "$(ls -A /home/container 2>/dev/null)" ]; then
    echo "Container kosong";
    if [ -n "${GIT_URL}" ]; then
        FULL_URL=$(build_git_url "${GIT_URL}");
        if [ -z "${GIT_BRANCH}" ]; then
            git clone "${FULL_URL}" /home/container;
        else
            git clone --single-branch --branch "${GIT_BRANCH}" "${FULL_URL}" /home/container;
        fi;
    fi;
fi;

if [ ! -f package.json ]; then
    echo "No package.json";
    exit 1;
fi;

corepack enable >/dev/null 2>&1 || true;
export NEXT_TELEMETRY_DISABLED=1;

if [ -f pnpm-lock.yaml ]; then
    PM="pnpm";
elif [ -f yarn.lock ]; then
    PM="yarn";
else
    PM="npm";
fi;
echo "PM: $PM";

if [ "${AUTO_UPDATE}" = "1" ] && [ -d .git ] && [ -n "${GIT_URL}" ]; then
    echo "Auto update: pulling latest changes...";
    FULL_URL=$(build_git_url "${GIT_URL}");
    git remote set-url origin "${FULL_URL}";
    git pull;
fi;

echo "Installing dependencies...";
if [ "$PM" = "pnpm" ]; then pnpm install; elif [ "$PM" = "yarn" ]; then yarn install; else npm install; fi;

if [ "${NODE_RUN_ENV}" = "start" ]; then
    echo "Build...";
    if [ "$PM" = "pnpm" ]; then pnpm run build; elif [ "$PM" = "yarn" ]; then yarn build; else npm run build; fi;
fi;

command -v pm2 >/dev/null 2>&1 || npm install -g pm2;

echo "Run mode: ${NODE_RUN_ENV}";

if [ "${NODE_RUN_ENV}" = "dev" ]; then
    if [ "$PM" = "pnpm" ]; then pm2 start pnpm --name app --no-autorestart=false -- dev -p ${SERVER_PORT};
    elif [ "$PM" = "yarn" ]; then pm2 start yarn --name app -- dev -p ${SERVER_PORT};
    else pm2 start npm --name app -- run dev -- -p ${SERVER_PORT}; fi;
else
    if [ "$PM" = "pnpm" ]; then pm2 start pnpm --name app -- start -p ${SERVER_PORT};
    elif [ "$PM" = "yarn" ]; then pm2 start yarn --name app -- start -p ${SERVER_PORT};
    else pm2 start npm --name app -- run start -- -p ${SERVER_PORT}; fi;
fi;

pm2 logs app --raw &

while read -r cmd; do
    if [ "$cmd" = "app-stop" ]; then
        echo "Stopping application via pm2...";
        pm2 delete app >/dev/null 2>&1;
        break;
    fi;
    if [ "${ENABLE_CONSOLE_CMD}" = "1" ]; then
        eval "$cmd";
    fi;
done
